    /*
     * Add to the Orders
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Contract
     */
    public Contract addToOrders( UUID parentId, Order addTo ) {
	    LOGGER.info("handling AssignOrdersToContractEvent - " );
	    
	    Contract parentEntity = repository.findById(parentId).get();
	    Order child = registry.project( Order.class, addTo.getOrderId());
	    
	    parentEntity.getOrders().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Orders
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Contract
     */
	public Contract removeFromOrders( UUID parentId, Order removeFrom ) {
	    LOGGER.info("handling RemoveOrdersFromContractEvent " );
	
	    Contract parentEntity = repository.findById(parentId).get();
	    Order child = registry.project( Order.class, removeFrom.getOrderId());
	    
	    parentEntity.getOrders().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

